// Aggregate all data sources into one context object
const calItems = $('Fetch Today\'s Calendar').all();
const weather = $('Fetch Weather').first()?.json;
const newsItems = $('Fetch News RSS').all().slice(0, 5);

// Calendar summary
const events = calItems.map(i => {
  const e = i.json;
  const start = e.start?.dateTime ? new Date(e.start.dateTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit', hour12: true }) : 'All day';
  return `${start}: ${e.summary || 'Untitled'}`;
});
const calSummary = events.length > 0 ? events.join('\n') : 'No meetings today';

// Weather summary
let weatherSummary = 'Weather unavailable';
if (weather?.main) {
  weatherSummary = `${Math.round(weather.main.temp)}°C, ${weather.weather?.[0]?.description || ''} — feels like ${Math.round(weather.main.feels_like)}°C`;
}

// News headlines
const headlines = newsItems.map(i => `- ${i.json.title}`).join('\n');

const name = $('Config').item.json.YOUR_NAME;
const city = $('Config').item.json.CITY;
const today = new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' });

return [{ json: { calSummary, weatherSummary, headlines, name, city, today, event_count: events.length } }];

